/* gerado por tools/mk_ctxh.py. Notas escritas por Claude a partir das fontes indicadas em cada uma. */
window.CTXH={"alice":{"intro":[{"t":"Lewis Carroll é pseudônimo de Charles Dodgson (1832–1898). Ele era matemático e dava aulas no Christ Church, em Oxford. Também fazia fotografia como hobby.","s":"Lewis Carroll (Wikipedia)","u":"https://en.wikipedia.org/wiki/Lewis_Carroll"},{"t":"Em 4 de julho de 1862, Carroll levou as três filhas do reitor Liddell num passeio de barco pelo rio perto de Oxford. Ele contou a elas a história que virou o livro.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"},{"t":"Alice Liddell pediu que ele escrevesse a história. Em 26 de novembro de 1864, ele deu a ela um manuscrito ilustrado à mão, com 37 desenhos. A Biblioteca Britânica guarda esse manuscrito.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"},{"t":"O livro saiu em novembro de 1865, pela editora Macmillan, com 42 gravuras de John Tenniel. A primeira tiragem foi recolhida, porque Tenniel não gostou da qualidade da impressão.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"},{"t":"Henry Liddell, pai de Alice, era o reitor (Dean) do Christ Church, a faculdade de Oxford onde Carroll trabalhava. A família chegou lá em 1856.","s":"Lewis Carroll (Wikipedia)","u":"https://en.wikipedia.org/wiki/Lewis_Carroll"},{"t":"O livro nunca saiu de catálogo e foi traduzido para 174 línguas. Carroll pagou do próprio bolso os 600 libras da nova impressão de 1865.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"}],"ch":{"2":[{"t":"Alice chama o rato de «O Mouse» porque tenta lembrar as declinações do latim, que aprendeu na gramática do irmão. É uma lembrança escolar da época.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"}],"3":[{"t":"Segundo a Wikipédia, o passeio de barco aparece aqui: o Dodô seria Carroll, o Pato seria seu amigo Robinson Duckworth, e o Lóri e a Aguiazinha seriam duas irmãs de Alice.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"},{"t":"O dodô era uma ave real da ilha Maurício. Foi vista pela última vez em 1662 e estava extinta por volta de 1700. O livro o tornou mundialmente conhecido.","s":"Dodo (Wikipedia)","u":"https://en.wikipedia.org/wiki/Dodo"},{"t":"«Caucus» é uma palavra política: reunião de membros de um partido. Surgiu nas colônias inglesas da América do Norte; o primeiro grupo ligado ao nome é de Boston, por volta de 1719.","s":"Caucus (Wikipedia)","u":"https://en.wikipedia.org/wiki/Caucus"}],"5":[{"t":"Os versos que Alice recita, «You Are Old, Father William», são uma paródia de um poema de Robert Southey sobre os confortos da velhice.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"}],"6":[{"t":"A expressão «sorrir como um gato de Cheshire» já existia antes do livro. Um dicionário de 1788 já a registra. Carroll usou uma frase que o público inglês conhecia.","s":"Cheshire Cat (Wikipedia)","u":"https://en.wikipedia.org/wiki/Cheshire_Cat"},{"t":"A canção de ninar da Duquesa é uma paródia de «Speak Gently», poema de David Bates.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"}],"7":[{"t":"«Louco como um chapeleiro» já era dito antes do livro: aparece impressa em 1829. Chapeleiros usavam mercúrio para fabricar feltro, e o veneno causava tremores e confusão.","s":"Mad as a hatter (Wikipedia)","u":"https://en.wikipedia.org/wiki/Mad_as_a_hatter"},{"t":"Alguns dizem que o Chapeleiro foi inspirado em Theophilus Carter, um vendedor de móveis de Oxford que usava cartola. Não há prova firme disso.","s":"Mad Hatter (Wikipedia)","u":"https://en.wikipedia.org/wiki/Mad_Hatter"},{"t":"O Leirão conta a história de três irmãs: Elsie, Lacie e Tillie. Segundo a Wikipédia, elas lembram as irmãs Liddell, e «Lacie» é um anagrama de «Alice».","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"}],"8":[{"t":"O croquet virou moda na Inglaterra nos anos 1860. Joga-se com taco de madeira e bola, passando a bola por arcos num gramado bem aparado.","s":"Croquet (Wikipedia)","u":"https://en.wikipedia.org/wiki/Croquet"},{"t":"No jogo da Rainha, as bolas são ouriços, os tacos são flamingos e os arcos são soldados dobrados. É o croquet comum virado do avesso.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"},{"t":"A Rainha de Copas é uma carta de baralho que fala. Sua frase mais famosa é «Cortem-lhe a cabeça!», que ela grita para resolver qualquer problema.","s":"Queen of Hearts (Wikipedia)","u":"https://en.wikipedia.org/wiki/Queen_of_Hearts_(Alice%27s_Adventures_in_Wonderland)"}],"9":[{"t":"A sopa de «falsa tartaruga» existia de verdade na Inglaterra. Era feita com cabeça de vitela para imitar a sopa de tartaruga, que era cara. A personagem tem corpo de tartaruga e cabeça e patas de bezerro.","s":"Mock turtle soup (Wikipedia)","u":"https://en.wikipedia.org/wiki/Mock_turtle_soup"},{"t":"O professor de desenho «conger» (um peixe tipo enguia) lembra John Ruskin, crítico de arte que ensinou desenho e pintura às crianças Liddell, segundo a Wikipédia.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"}],"10":[{"t":"A quadrilha era uma dança de salão em moda no século XIX. Era dançada em quadrado, normalmente com quatro casais. Chegou à alta sociedade inglesa em 1816.","s":"Quadrille (Wikipedia)","u":"https://en.wikipedia.org/wiki/Quadrille"},{"t":"O poema «'Tis the Voice of the Lobster» é uma paródia de «The Sluggard», poema de Isaac Watts, segundo a Wikipédia.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"}],"11":[{"t":"«The Queen of Hearts» é uma cantiga infantil inglesa de verdade. Carroll a coloca no livro, e é o tema do julgamento deste capítulo.","s":"Alice's Adventures in Wonderland (Wikipedia)","u":"https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland"}],"12":[{"t":"Nas últimas cenas, a Rainha condena Alice por defender o Valete, e dá a sentença antes do veredito.","s":"Queen of Hearts (Wikipedia)","u":"https://en.wikipedia.org/wiki/Queen_of_Hearts_(Alice%27s_Adventures_in_Wonderland)"}]}},"frank":{"intro":[{"t":"A primeira edição saiu em Londres em 1º de janeiro de 1818, sem o nome da autora. Foram só 500 cópias, em três volumes. O prefácio foi escrito pelo marido dela, Percy Shelley.","s":"Frankenstein – Wikipedia","u":"https://en.wikipedia.org/wiki/Frankenstein"},{"t":"Mary Shelley tinha 18 anos quando começou a história, em junho de 1816, e 20 quando o livro saiu. O nome dela só apareceu na edição de 1823.","s":"Mary Shelley – Wikipedia","u":"https://en.wikipedia.org/wiki/Mary_Shelley"},{"t":"Em junho de 1816, Mary, Percy Shelley, Lord Byron e o médico dele, Polidori, ficaram presos pela chuva numa casa perto do lago de Genebra. Byron propôs que cada um escrevesse uma história de fantasmas.","s":"Villa Diodati – Wikipedia","u":"https://en.wikipedia.org/wiki/Villa_Diodati"},{"t":"O frio de 1816 veio do vulcão Tambora, na Indonésia, que entrou em erupção em 1815. Foi o verão mais frio da Europa entre 1766 e 2000, e as colheitas falharam. Por isso chamam 1816 de «ano sem verão».","s":"Year Without a Summer – Wikipedia","u":"https://en.wikipedia.org/wiki/Year_Without_a_Summer"},{"t":"A mãe de Mary, Mary Wollstonecraft, escreveu em 1792 um livro defendendo que as mulheres precisam de educação. Ela morreu cerca de 11 dias depois do parto. O pai, William Godwin, criou Mary.","s":"Mary Wollstonecraft – Wikipedia","u":"https://en.wikipedia.org/wiki/Mary_Wollstonecraft"},{"t":"A edição de 1831 foi bastante revisada por Mary em uma versão de um volume só. É a mais lida hoje. Nela, Mary conta que ouviu falar de experimentos do Dr. Darwin que inspiraram a história.","s":"Frankenstein – Wikipedia","u":"https://en.wikipedia.org/wiki/Frankenstein"}],"ch":{"1":[{"t":"Walton quer achar uma rota pelo norte. Em 1775 o governo britânico ofereceu um prêmio de 20 mil libras por uma passagem no Ártico. James Cook tentou em 1776, pelo lado do Pacífico, e não achou nada.","s":"Northwest Passage – Wikipedia","u":"https://en.wikipedia.org/wiki/Northwest_Passage"},{"t":"São Petersburgo foi fundada em 1703 por Pedro, o Grande, no rio Neva. Fica a cerca de 60° de latitude norte e foi capital do Império Russo de 1712 a 1918. É de onde Walton escreve.","s":"Saint Petersburg – Wikipedia","u":"https://en.wikipedia.org/wiki/Saint_Petersburg"}],"2":[{"t":"Walton conta que foi marinheiro num baleeiro da Groenlândia. A caça britânica à baleia no Ártico foi grande: perto de 250 navios no auge, em 1786-1788. O óleo servia para iluminar ruas e lubrificar máquinas.","s":"Whaling in the United Kingdom – Wikipedia","u":"https://en.wikipedia.org/wiki/Whaling_in_the_United_Kingdom"},{"t":"Walton cita «O Velho Marinheiro», poema de Samuel Taylor Coleridge. Foi publicado em 1798 no livro Lyrical Ballads. Nele, um marinheiro mata um albatroz que guiava o navio e carrega a maldição.","s":"The Rime of the Ancient Mariner – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Rime_of_the_Ancient_Mariner"}],"3":[{"t":"Arcangel fica no rio Dvina do Norte, perto do Mar Branco. Foi o principal porto da Rússia até 1703, quando São Petersburgo tomou o lugar. Comerciantes ingleses negociavam lá desde 1555. O gelo de inverno limita o porto.","s":"Arkhangelsk – Wikipedia","u":"https://en.wikipedia.org/wiki/Arkhangelsk"}],"5":[{"t":"Genebra fica na ponta sudoeste do lago Léman (lago de Genebra), onde o rio Ródano sai. Calvino virou líder espiritual da cidade em 1541. Genebra entrou na Confederação Suíça em 1815.","s":"Geneva – Wikipedia","u":"https://en.wikipedia.org/wiki/Geneva"},{"t":"O lago de Como fica na Lombardia, norte da Itália, a uns 45 km de Milão. Tem forma de Y e foi escavado por uma geleira. Passa de 400 metros de profundidade.","s":"Lake Como – Wikipedia","u":"https://en.wikipedia.org/wiki/Lake_Como"}],"6":[{"t":"Victor lê Agrippa, Paracelso e Alberto Magno. Agrippa (1486-1535) escreveu sobre ocultismo e teve o livro principal condenado por um inquisidor de Colônia. Paracelso (1493-1541) era médico suíço e alquimista, e usava remédios minerais.","s":"Heinrich Cornelius Agrippa – Wikipedia","u":"https://en.wikipedia.org/wiki/Heinrich_Cornelius_Agrippa"},{"t":"Galvanismo: nos anos 1780-1790, Luigi Galvani viu pernas de rã se contraírem ao toque de metais. Achou que era «eletricidade animal». Volta discordou e criou a pilha. O termo «galvanismo» ficou para a eletricidade química.","s":"Galvanism – Wikipedia","u":"https://en.wikipedia.org/wiki/Galvanism"}],"7":[{"t":"A Universidade de Ingolstadt, na Baviera, foi fundada em 1472. Mudou-se para Landshut em 1800 e para Munique em 1826. Hoje a Velha Anatomia da cidade abriga o Museu Alemão de História da Medicina.","s":"Ingolstadt – Wikipedia","u":"https://en.wikipedia.org/wiki/Ingolstadt"},{"t":"Alberto Magno (cerca de 1200-1280) era um frade dominicano alemão. Escreveu sobre plantas, animais e minerais. Foi professor de Tomás de Aquino e, em 1941, virou padroeiro dos cientistas naturais.","s":"Albertus Magnus – Wikipedia","u":"https://en.wikipedia.org/wiki/Albertus_Magnus"}],"8":[{"t":"Em 1803, em Londres, Giovanni Aldini (sobrinho de Galvani) aplicou eletricidade ao corpo de um condenado executado, George Foster. Segundo os relatos, mandíbula, rosto, mão e pernas se mexeram.","s":"Galvanism – Wikipedia","u":"https://en.wikipedia.org/wiki/Galvanism"}],"11":[{"t":"O Monte Branco (4.807 m) fica entre a França e a Itália. A primeira subida registrada foi em 8 de agosto de 1786, por Jacques Balmat e Michel-Gabriel Paccard. Essa subida marca o começo do alpinismo moderno.","s":"Mont Blanc – Wikipedia","u":"https://en.wikipedia.org/wiki/Mont_Blanc"}],"14":[{"t":"A Mer de Glace é uma geleira de 7,5 km de comprimento no lado norte do Monte Branco, acima do vale de Chamonix. No século XIX, visitantes e pintores iam vê-la. Turner pintou uma cena da região em 1816.","s":"Mer de Glace – Wikipedia","u":"https://en.wikipedia.org/wiki/Mer_de_Glace"}],"19":[{"t":"A criatura lê «Paraíso Perdido», poema de John Milton publicado em 1667, em dez livros (a edição de 1674 passou a doze). Conta a queda de Adão e Eva e a tentação feita por Satã.","s":"Paradise Lost – Wikipedia","u":"https://en.wikipedia.org/wiki/Paradise_Lost"},{"t":"Os Sofrimentos do Jovem Werther, de Goethe, saiu em 1774, escrito em cartas. Foi um dos primeiros best-sellers internacionais. Causou a «febre Werther»: jovens passaram a imitar a roupa do personagem.","s":"The Sorrows of Young Werther – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Sorrows_of_Young_Werther"}],"22":[{"t":"Em 1814, Mary e Percy Shelley fizeram uma viagem de seis semanas pela França e pela Suíça. Sem dinheiro, voltaram descendo o rio Reno até a Holanda. O diário foi publicado em 1817.","s":"Mary Shelley – Wikipedia","u":"https://en.wikipedia.org/wiki/Mary_Shelley"}],"23":[{"t":"As Órcades são um arquipélago a cerca de 16 km ao norte da Escócia continental. Têm uns 70 ilhas, das quais 20 habitadas. O vento é quase constante, com média de cerca de 52 horas de ventania por ano.","s":"Orkney – Wikipedia","u":"https://en.wikipedia.org/wiki/Orkney"}],"28":[{"t":"Muitas expedições ao Ártico acabaram em desastre. A de John Franklin, em 1845, teve dois navios presos no gelo perto da ilha King William, em 1846. Franklin morreu em 1847 e não se achou nenhum sobrevivente.","s":"Northwest Passage – Wikipedia","u":"https://en.wikipedia.org/wiki/Northwest_Passage"}]}},"grimm":{"intro":[{"t":"Jacob (nascido em 1785) e Wilhelm (1786) Grimm nasceram em Hanau, na Alemanha. Trabalharam como bibliotecários e, a partir de 1830, como professores na Universidade de Göttingen.","s":"Brothers Grimm – Wikipedia","u":"https://en.wikipedia.org/wiki/Brothers_Grimm"},{"t":"Em 1807, a pedido do escritor Clemens Brentano, os irmãos começaram a recolher contos populares. Convidavam narradores para ir à casa deles e anotavam o que ouviam. Os textos eram bastante modificados ao serem escritos.","s":"Brothers Grimm – Wikipedia","u":"https://en.wikipedia.org/wiki/Brothers_Grimm"},{"t":"O primeiro volume saiu em 1812, com 86 contos. O segundo, de 1815, trouxe mais 70. A sétima e última edição, de 1857, chegou a cerca de 210 contos.","s":"Grimms' Fairy Tales – Wikipedia","u":"https://en.wikipedia.org/wiki/Grimms%27_Fairy_Tales"},{"t":"Dorothea Viehmann, mulher de um alfaiate e de família huguenote, contou aos Grimm mais de quarenta contos a partir de 1813. Outras fontes foram Dortchen Wild e Marie Hassenpflug, mulheres de classe média ou aristocráticas.","s":"Dorothea Viehmann – Wikipedia","u":"https://en.wikipedia.org/wiki/Dorothea_Viehmann"},{"t":"Entre as edições, os Grimm retiraram referências sexuais. Em compensação, a violência nos castigos dos vilões aumentou. Os primeiros volumes tinham sido criticados por serem pouco adequados a crianças.","s":"Grimms' Fairy Tales – Wikipedia","u":"https://en.wikipedia.org/wiki/Grimms%27_Fairy_Tales"},{"t":"A tradução inglesa usada aqui é de Margaret Hunt (1831-1912), publicada em 1884 em dois volumes, com introdução de Andrew Lang.","s":"Margaret Raine Hunt – Wikipedia","u":"https://en.wikipedia.org/wiki/Margaret_Raine_Hunt"}],"ch":{"1":[{"t":"Os estudiosos classificam este conto como tipo 709 no sistema Aarne-Thompson. Existem versões alemãs anteriores, como a peça de teatro «Schneewittchen», de Albert Ludwig Grimm (1809).","s":"Snow White – Wikipedia","u":"https://en.wikipedia.org/wiki/Snow_White"},{"t":"Na primeira edição, a vilã de Branca de Neve era a mãe da menina. Nas edições seguintes ela virou madrasta, mudança que ajudou a deixar a história mais suave para crianças.","s":"Grimms' Fairy Tales – Wikipedia","u":"https://en.wikipedia.org/wiki/Grimms%27_Fairy_Tales"}],"2":[{"t":"Na versão dos Grimm não há fada madrinha. A ajuda vem de uma árvore que cresce no túmulo da mãe, regada com lágrimas, e de pássaros brancos que trazem as roupas.","s":"Cinderella – Wikipedia","u":"https://en.wikipedia.org/wiki/Cinderella"},{"t":"Perrault (1697) acrescentou a fada madrinha, a carruagem de abóbora e os sapatinhos de vidro. Antes dele, Basile (1634) contou a história de Zezolla, e uma versão chinesa de cerca de 860 já existia.","s":"Cinderella – Wikipedia","u":"https://en.wikipedia.org/wiki/Cinderella"}],"3":[{"t":"Os Grimm tiraram o conto de uma versão alemã de 1790, de Friedrich Schulz. Ela traduzia «Persinette» (1698), que por sua vez vinha de «Petrosinella», de Basile (1634). Schulz deu à moça o nome Rapunzel.","s":"Rapunzel – Wikipedia","u":"https://en.wikipedia.org/wiki/Rapunzel"},{"t":"Em 1812, a gravidez de Rapunzel revelava as visitas do príncipe. Na edição de 1857 isso foi trocado por um deslize da moça. «Rapunzel» é uma planta, rapúncio ou erva-benta, desejada pela grávida.","s":"Rapunzel – Wikipedia","u":"https://en.wikipedia.org/wiki/Rapunzel"}],"4":[{"t":"Publicado em 1812 como KHM 15. Estudiosos acreditam que os Grimm ouviram a história em 1809, na família Wild, de Dortchen, futura esposa de Wilhelm. É o tipo 327A, o das crianças abandonadas.","s":"Hansel and Gretel – Wikipedia","u":"https://en.wikipedia.org/wiki/Hansel_and_Gretel"},{"t":"Em 1812, a mulher do lenhador era mãe das crianças. Ela só virou madrasta na quarta edição, de 1840. A casa da bruxa, nos Grimm, é de pão, bolo e açúcar. A casa de biscoito de gengibre popularizou-se com uma ópera de 1893.","s":"Hansel and Gretel – Wikipedia","u":"https://en.wikipedia.org/wiki/Hansel_and_Gretel"}],"5":[{"t":"A versão impressa mais antiga é de Perrault (1697): a menina é devorada e ninguém a salva. Os Grimm (1812) acrescentam o caçador, que abre a barriga do lobo e liberta a menina e a avó.","s":"Little Red Riding Hood – Wikipedia","u":"https://en.wikipedia.org/wiki/Little_Red_Riding_Hood"},{"t":"Segundo a fonte, Jeanette Hassenpflug contou o conto principal aos Grimm. Uma versão oral italiana do século XIV, «A falsa avó», já tinha a menina escapando sozinha por esperteza. O tipo é o 333.","s":"Little Red Riding Hood – Wikipedia","u":"https://en.wikipedia.org/wiki/Little_Red_Riding_Hood"}],"6":[{"t":"Os primeiros traços da história aparecem no romance francês «Perceforest» (cerca de 1337-1344). Basile (1634-36) fez a primeira versão literária completa. Perrault a suavizou em 1697.","s":"Sleeping Beauty – Wikipedia","u":"https://en.wikipedia.org/wiki/Sleeping_Beauty"},{"t":"Os Grimm partiram de Perrault e acrescentaram a cerca de espinhos. Terminam quando a princesa acorda e cortam a segunda parte, com a ogra. As fadas viram «mulheres sábias».","s":"Sleeping Beauty – Wikipedia","u":"https://en.wikipedia.org/wiki/Sleeping_Beauty"}],"7":[{"t":"É o primeiro conto da coletânea (KHM 1), com o título «O Rei Sapo ou Henrique de Ferro». Na versão de 1812, a princesa não beija o sapo: ela se enfurece e o atira contra a parede.","s":"The Frog Prince – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Frog_Prince"},{"t":"Henrique de Ferro é o criado fiel do príncipe. Três cintas de ferro prendiam seu coração para ele não se partir de tristeza. Elas estouram quando o príncipe volta à forma humana.","s":"The Frog Prince – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Frog_Prince"}],"8":[{"t":"Publicado em 1812 como KHM 55, o conto é do tipo 500, «o nome do ajudante sobrenatural». Na edição de 1812 o duende foge furioso. Em 1857 ele se despedaça de raiva.","s":"Rumpelstiltskin – Wikipedia","u":"https://en.wikipedia.org/wiki/Rumpelstiltskin"},{"t":"Há histórias parecidas em outros países, como «Tom Tit Tot» (Inglaterra, coletada por Joseph Jacobs em 1890), «Whuppity Stoorie» (Escócia) e «Gilitrutt» (Islândia).","s":"Rumpelstiltskin – Wikipedia","u":"https://en.wikipedia.org/wiki/Rumpelstiltskin"}],"9":[{"t":"Entrou na segunda edição, de 1819, como KHM 27, com base em relato de Dorothea Viehmann. Apesar do título, os animais nunca chegam a Bremen: eles ficam na casa dos ladrões.","s":"Town Musicians of Bremen – Wikipedia","u":"https://en.wikipedia.org/wiki/Town_Musicians_of_Bremen"},{"t":"Em Bremen há uma estátua de bronze dos animais, feita por Gerhard Marcks e erguida em 1953. O tipo do conto é o 130, «os animais no alojamento da noite».","s":"Town Musicians of Bremen – Wikipedia","u":"https://en.wikipedia.org/wiki/Town_Musicians_of_Bremen"}],"10":[{"t":"Saiu em 1815, no segundo volume da primeira edição, com o número 47. Nas edições seguintes virou KHM 133. A fonte cita Jenny von Droste-Hülshoff, que contou a história aos Grimm.","s":"The Twelve Dancing Princesses – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Twelve_Dancing_Princesses"},{"t":"É o tipo 306. A versão escocesa «Kate Crackernuts» é a mais parecida, mas quem dança é um príncipe. Na versão de Paderborn há três princesas e aparece o truque do vinho com sonífero.","s":"The Twelve Dancing Princesses – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Twelve_Dancing_Princesses"}],"11":[{"t":"O conto é do tipo 571, «todos grudam». O episódio final do navio que anda na terra e na água é do tipo 513B. Os Grimm trazem a história com o número KHM 64.","s":"The Golden Goose – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Golden_Goose"}],"12":[{"t":"É o tipo 554, «os animais agradecidos» (KHM 62). Ludwig Bechstein publicou, em 1847, uma variante, «A princesa encantada», com dois irmãos e uma velha no lugar do anão.","s":"The Queen Bee – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Queen_Bee_(fairy_tale)"}],"13":[{"t":"Na primeira edição, de 1812, o conto se chamava «Os três corvos». A edição de 1819 trocou o título para «Os sete corvos» e reescreveu bastante a história. A família Hassenpflug está entre as fontes.","s":"The Seven Ravens – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Seven_Ravens"},{"t":"É o tipo 451, «a moça que procura os irmãos». Contos parecidos incluem «Os seis cisnes» e «Os doze irmãos».","s":"The Seven Ravens – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Seven_Ravens"}],"14":[{"t":"Foi publicado em 1812 como KHM 19. O manuscrito veio do pintor Philipp Otto Runge, em 1809, e o título original está em baixo-alemão: «Von dem Fischer un syner Fru».","s":"The Fisherman and His Wife – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Fisherman_and_His_Wife"},{"t":"É o tipo 555, sobre ambição e descontentamento. O poeta russo Aleksandr Púchkin escreveu em 1833 o poema «O conto do pescador e do peixe», que usa o mesmo tema.","s":"The Fisherman and His Wife – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Fisherman_and_His_Wife"}],"15":[{"t":"Publicado em 1812, o conto veio de Dortchen Wild, amiga e futura esposa de Wilhelm. É o tipo 480, «a boa e a má moça». Em partes da Hesse diz-se «Holle está arrumando a cama» quando neva.","s":"Frau Holle – Wikipedia","u":"https://en.wikipedia.org/wiki/Mother_Holle"},{"t":"A edição de 1857 mudou duas coisas: as irmãs passaram a ser meias-irmãs, e buscar água foi trocado por fiar. O galo que canta já tinha sido acrescentado em 1819.","s":"Frau Holle – Wikipedia","u":"https://en.wikipedia.org/wiki/Mother_Holle"}],"16":[{"t":"Saiu na primeira edição, de 1812, como KHM 5. A fonte foi a família Hassenpflug, de Hanau. É o tipo 123, «o lobo e os cabritinhos».","s":"The Wolf and the Seven Young Goats – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Wolf_and_the_Seven_Young_Kids"},{"t":"A história tem antecedentes: uma fábula de Esopo, uma versão de Marie de France e outra de La Fontaine. Na versão dos Grimm, o caçula escapa escondido na caixa do relógio de parede.","s":"The Wolf and the Seven Young Goats – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Wolf_and_the_Seven_Young_Kids"}],"17":[{"t":"O título alemão é «Die Wichtelmänner» (KHM 39, 1812). O verbete reúne três histórias, e Hunt deu o mesmo título, «The Elves», às três. A fonte cita Gretchen Wild como informante.","s":"The Elves and the Shoemaker – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Elves_and_the_Shoemaker"},{"t":"Quando a mulher do sapateiro faz roupas e sapatos para os duendes, eles se alegram, saem dançando e nunca voltam. O sapateiro continua prosperando.","s":"The Elves and the Shoemaker – Wikipedia","u":"https://en.wikipedia.org/wiki/The_Elves_and_the_Shoemaker"}]}},"perrault":{"intro":[{"t":"Charles Perrault (1628–1703) nasceu em Paris numa família rica e estudou direito. Trabalhou para o ministro Colbert, de Luís XIV, e foi eleito para a Académie française em 1671.","s":"Charles Perrault (Wikipedia)","u":"https://en.wikipedia.org/wiki/Charles_Perrault"},{"t":"Perrault liderou os «Modernos» na Querela dos Antigos e dos Modernos: defendia que a literatura do tempo de Luís XIV valia mais que a da Antiguidade. Perdeu seus cargos na corte e, depois de 1695, se dedicou aos filhos.","s":"Charles Perrault (Wikipedia)","u":"https://en.wikipedia.org/wiki/Charles_Perrault"},{"t":"O livro saiu em Paris em 1697, pelo editor Claude Barbin, com oito contos e uma «moralidade» em verso no fim de cada um. O subtítulo popular era «Contos da Mamãe Gansa». A capa mostra uma velha fiando e contando histórias a crianças.","s":"Histoires ou contes du temps passé (Wikipedia)","u":"https://en.wikipedia.org/wiki/Histoires_ou_contes_du_temps_pass%C3%A9"},{"t":"A folha de rosto traz o nome «P. Darmancour», do filho de Perrault, Pierre, então com cerca de 19 anos. Hoje os estudiosos consideram Charles quase certamente o autor. O livro é dedicado a Élisabeth Charlotte d'Orléans, sobrinha do rei.","s":"Histoires ou contes du temps passé (Wikipedia)","u":"https://en.wikipedia.org/wiki/Histoires_ou_contes_du_temps_pass%C3%A9"},{"t":"Nos salões de Paris, no fim do século XVII, contar contos de fadas virou moda entre aristocratas. Perrault escreveu para esse público refinado e tirou dos contos populares os traços mais grosseiros.","s":"Histoires ou contes du temps passé (Wikipedia)","u":"https://en.wikipedia.org/wiki/Histoires_ou_contes_du_temps_pass%C3%A9"},{"t":"A expressão «conte de fées» vem da coleção de Madame d'Aulnoy, de 1697. Os contos de Perrault fixaram as formas hoje famosas de «A Bela Adormecida» e «Cinderela» e influenciaram os irmãos Grimm.","s":"Fairy tale (Wikipedia)","u":"https://en.wikipedia.org/wiki/Fairy_tale"}],"ch":{"1":[{"t":"A dedicatória vai para Élisabeth Charlotte d'Orléans, sobrinha de Luís XIV. A carta diz que seria surpreendente um jovem de cerca de 19 anos compor os contos. Uma hipótese é que o nome de Pierre servia para apresentar o rapaz à sociedade.","s":"Histoires ou contes du temps passé (Wikipedia)","u":"https://en.wikipedia.org/wiki/Histoires_ou_contes_du_temps_pass%C3%A9"}],"2":[{"t":"A versão mais antiga com enredo completo é «Sol, Lua e Talia», de Basile (publicada em 1634-1636). Perrault, em 1697, trouxe o fuso, as sete fadas e o sono de cem anos.","s":"Sleeping Beauty (Wikipedia)","u":"https://en.wikipedia.org/wiki/Sleeping_Beauty"},{"t":"Segundo a Wikipédia, o Château d'Ussé serviu de cenário real para este conto. Os irmãos Grimm publicaram sua versão, «Rosa-de-espinhos», em 1812, derivada da de Perrault.","s":"Charles Perrault (Wikipedia)","u":"https://en.wikipedia.org/wiki/Charles_Perrault"}],"3":[{"t":"Contos orais mais antigos já existiam na França e na Itália, e o vilão às vezes era um lobisomem. Perrault foi o primeiro a imprimir o conto e a introduzir a cor vermelha do capuz.","s":"Little Red Riding Hood (Wikipedia)","u":"https://en.wikipedia.org/wiki/Little_Red_Riding_Hood"},{"t":"Em Perrault não há caçador nem final feliz: o lobo vence. A moral avisa que as moças não devem dar ouvidos a estranhos e que os lobos «gentis» são os mais perigosos.","s":"Little Red Riding Hood (Wikipedia)","u":"https://en.wikipedia.org/wiki/Little_Red_Riding_Hood"}],"4":[{"t":"Perrault publicou o conto em 1697. Ele pertence ao tipo ATU 312, «O assassino de moças», aparentado ao tipo 311.","s":"Bluebeard (Wikipedia)","u":"https://en.wikipedia.org/wiki/Bluebeard"},{"t":"Muita gente liga Barba Azul a Gilles de Rais, nobre do século XV executado por assassinatos. A ligação é fraca: ele não matou esposas, e não há prova de que Perrault o conhecesse.","s":"Bluebeard (Wikipedia)","u":"https://en.wikipedia.org/wiki/Bluebeard"}],"5":[{"t":"A história mais antiga conhecida é de Straparola (por volta de 1550), com um gato que é uma fada. Basile contou outra versão em 1634. Perrault, em 1697, acrescentou as botas e o nome «Marquês de Carabás».","s":"Puss in Boots (Wikipedia)","u":"https://en.wikipedia.org/wiki/Puss_in_Boots"},{"t":"Segundo a Wikipédia, o marquês de Oiron teria servido de modelo para o Marquês de Carabás.","s":"Charles Perrault (Wikipedia)","u":"https://en.wikipedia.org/wiki/Charles_Perrault"}],"6":[{"t":"Perrault chamou o conto de «Les Fées». Na fonte que ele usou, a moça boa era a enteada; ele a fez filha, provavelmente para parecer menos com a Cinderela.","s":"Diamonds and Toads (Wikipedia)","u":"https://en.wikipedia.org/wiki/Diamonds_and_Toads"},{"t":"É o tipo ATU 480, «a menina boa e a menina má». Contos parecidos incluem «Mãe Hulda» (Frau Holle), dos Grimm.","s":"Diamonds and Toads (Wikipedia)","u":"https://en.wikipedia.org/wiki/Diamonds_and_Toads"}],"7":[{"t":"Perrault popularizou a fada madrinha, a abóbora que vira carruagem, a meia-noite como limite e o sapatinho de vidro. Versões mais antigas incluem Rhodopis (Grécia), Ye Xian (China, por volta de 860) e Cenerentola, de Basile (1634).","s":"Cinderella (Wikipedia)","u":"https://en.wikipedia.org/wiki/Cinderella"},{"t":"Há quem diga que «pantoufle de verre» (vidro) seria erro de «vair» (pele de esquilo). A maioria dos estudiosos vê o vidro como invenção poética de Perrault.","s":"Cinderella (Wikipedia)","u":"https://en.wikipedia.org/wiki/Cinderella"},{"t":"«Vair» era a pele do esquilo-vermelho, azul-acinzentada nas costas e branca na barriga. Era usada para forrar mantos de nobres e reis na Idade Média.","s":"Vair (Wikipedia)","u":"https://en.wikipedia.org/wiki/Vair"}],"8":[{"t":"Catherine Bernard publicou uma versão em 1696, no romance «Inès de Cordoue», e inspirou Perrault. No final dela, a princesa se casa por medo, e o tom é amargo. Na de Perrault, o amor muda o olhar sobre o amado.","s":"Riquet with the Tuft (Wikipedia)","u":"https://en.wikipedia.org/wiki/Riquet_with_the_Tuft"},{"t":"O nome «Riquet» pode brincar com a família Riquetti, ou lembrar Pierre-Paul Riquet, do Canal do Languedoc, ou ser apelido de Henriquet («pequeno Henrique»).","s":"Riquet with the Tuft (Wikipedia)","u":"https://en.wikipedia.org/wiki/Riquet_with_the_Tuft"}],"9":[{"t":"«Poucet» vem de «pouce», polegar. A primeira metade lembra «João e Maria»: pais pobres abandonam os filhos na floresta, e os pássaros comem as migalhas da trilha. A segunda mostra o menino enganando um ogro e roubando suas botas de sete léguas.","s":"Hop-o'-My-Thumb (Wikipedia)","u":"https://en.wikipedia.org/wiki/Hop-o%27-My-Thumb"},{"t":"Poucos anos antes do livro houve a grande fome francesa de 1693-1694: o pão ficou muito mais caro e morreram de 1,3 a 2 milhões de pessoas. A fonte não liga a fome ao conto.","s":"Famine and Inflation in 17th-Century France (EBSCO Research Starters)","u":"https://ebsco.com/research-starters/history/famine-and-inflation-17th-century-france"}]}},"peter":{"intro":[{"t":"Beatrix Potter nasceu em 28 de julho de 1866, em Londres, numa família rica ligada ao algodão. Estudou em casa com governantas e teve poucos amigos fora da família.","s":"Beatrix Potter - Britannica","u":"https://www.britannica.com/biography/Beatrix-Potter"},{"t":"A história começou em 1893 como uma carta ilustrada para Noel Moore, menino de cinco anos que se recuperava de escarlatina. Ele era filho da antiga governanta de Potter.","s":"The Tale of Peter Rabbit - Wikipedia","u":"https://en.wikipedia.org/wiki/The_Tale_of_Peter_Rabbit"},{"t":"Várias editoras recusaram o livro. Potter o imprimiu por conta própria em 1901. Em 1902, a Frederick Warne & Co. o publicou, agora com ilustrações coloridas.","s":"The Tale of Peter Rabbit - Wikipedia","u":"https://en.wikipedia.org/wiki/The_Tale_of_Peter_Rabbit"},{"t":"Em dezembro de 1903, o livro já tinha vendido 50 mil exemplares. Hoje foi traduzido para 36 idiomas e vendeu mais de 45 milhões de cópias.","s":"The Tale of Peter Rabbit - Wikipedia","u":"https://en.wikipedia.org/wiki/The_Tale_of_Peter_Rabbit"},{"t":"Com o dinheiro dos livros, Potter comprou em 1905 a fazenda Hill Top, na região dos Lagos. Ao morrer, em 1943, deixou ao National Trust mais de 4 mil acres e 16 fazendas.","s":"Beatrix Potter - Wikipedia","u":"https://en.wikipedia.org/wiki/Beatrix_Potter"},{"t":"Em 1903, Potter patenteou um boneco do Peter Rabbit e logo lançou um jogo de tabuleiro. Foi uma das primeiras vezes em que um personagem de livro virou mercadoria.","s":"The Tale of Peter Rabbit - Wikipedia","u":"https://en.wikipedia.org/wiki/The_Tale_of_Peter_Rabbit"}],"ch":{"1":[{"t":"No livro, o pai de Peter foi pego na horta do Sr. McGregor e virou recheio de torta, feita pela Sra. McGregor. Por isso a mãe avisa os filhos para não entrarem lá.","s":"The Tale of Peter Rabbit - Wikipedia","u":"https://en.wikipedia.org/wiki/The_Tale_of_Peter_Rabbit"},{"t":"Peter perde o casaco e os sapatos na fuga. Depois, as roupas aparecem num espantalho. Espantalhos costumam usar roupas velhas e servem para afastar pássaros das plantações.","s":"Scarecrow - Wikipedia","u":"https://en.wikipedia.org/wiki/Scarecrow"},{"t":"No fim, Peter volta doente e é mandado para a cama sem jantar. A mãe lhe dá uma colher de chá de camomila. As irmãs comem pão, leite e amoras.","s":"The Tale of Peter Rabbit - Wikipedia","u":"https://en.wikipedia.org/wiki/The_Tale_of_Peter_Rabbit"}]}},"principe":{"intro":[{"t":"Maquiavel escreveu «O Príncipe» em 1513, com o título latino «De Principatibus». O livro só foi publicado em 1532, cinco anos depois da morte dele, com permissão do papa Clemente VII, também um Médici.","s":"The Prince (Wikipedia)","u":"https://en.wikipedia.org/wiki/The_Prince"},{"t":"Maquiavel, florentino, nasceu em 1469. De 1498 a 1512 foi secretário da República de Florença e fez missões diplomáticas, inclusive à França e ao papado.","s":"Niccolò Machiavelli (Wikipedia)","u":"https://en.wikipedia.org/wiki/Niccol%C3%B2_Machiavelli"},{"t":"Em 1512 os Médici voltaram ao poder em Florença e Maquiavel perdeu o cargo. Foi preso, torturado e solto depois de cerca de três semanas. Foi então viver na sua fazenda e passou a escrever.","s":"Niccolò Machiavelli (Wikipedia)","u":"https://en.wikipedia.org/wiki/Niccol%C3%B2_Machiavelli"},{"t":"O livro é um «espelho de príncipes»: um manual para quem governa. Era incomum porque falava de príncipes novos, e não só dos que herdam o trono. Começa com uma carta de dedicatória e termina pedindo a unificação da Itália.","s":"The Prince (Wikipedia)","u":"https://en.wikipedia.org/wiki/The_Prince"},{"t":"A Itália da época vivia as Guerras da Itália (1494-1559): França, Espanha e o Império lutavam pelo território italiano. A guerra começou quando Carlos VIII da França invadiu Nápoles em 1494.","s":"Italian Wars (Wikipedia)","u":"https://en.wikipedia.org/wiki/Italian_Wars"},{"t":"Os Médici eram uma família de banqueiros de Florença. Foram expulsos da cidade de 1494 a 1512. Em 1513 um deles virou o papa Leão X, e em 1532 receberam o título de duques de Florença.","s":"House of Medici (Wikipedia)","u":"https://en.wikipedia.org/wiki/House_of_Medici"}],"ch":{"1":[{"t":"O livro foi dedicado a Lorenzo de Médici, duque de Urbino, nascido em Florença em 1492. Ele morreu em 1519, aos 26 anos. Sua filha Catarina de Médici se tornou rainha da França.","s":"Lorenzo di Piero de' Medici, Duke of Urbino (Wikipedia)","u":"https://en.wikipedia.org/wiki/Lorenzo_di_Piero_de%27_Medici,_Duke_of_Urbino"},{"t":"A primeira ideia era dedicar o livro a Giuliano de Médici, tio de Lorenzo, irmão do papa Leão X. Giuliano nasceu em 1479, governou Florença em 1513 e morreu em 1516.","s":"Giuliano di Lorenzo de' Medici (Wikipedia)","u":"https://en.wikipedia.org/wiki/Giuliano_di_Lorenzo_de%27_Medici"}],"2":[{"t":"Francesco Sforza foi um condottiero (capitão mercenário). Casou-se em 1441 com Bianca Maria Visconti e, em 1450, tornou-se duque de Milão.","s":"Francesco I Sforza (Wikipedia)","u":"https://en.wikipedia.org/wiki/Francesco_I_Sforza"},{"t":"O livro classifica os principados em hereditários, novos, mistos, civis e eclesiásticos. Os capítulos seguintes tratam de cada tipo, do exército e das qualidades do príncipe.","s":"The Prince (Wikipedia)","u":"https://en.wikipedia.org/wiki/The_Prince"}],"4":[{"t":"Luís XII, rei da França de 1498 a 1515, reivindicava Milão por herança dos Visconti. Entrou em Milão em outubro de 1499. Em 1501 suas tropas entraram em Nápoles.","s":"Louis XII of France (Wikipedia)","u":"https://en.wikipedia.org/wiki/Louis_XII_of_France"},{"t":"Ludovico Sforza, o Mouro, foi duque de Milão de 1494 a 1499. Maquiavel o culpava por ter chamado Carlos VIII à Itália. Os franceses o prenderam em 1500. Ele protegeu Leonardo da Vinci.","s":"Ludovico Sforza (Wikipedia)","u":"https://en.wikipedia.org/wiki/Ludovico_Sforza"}],"5":[{"t":"Dario III foi o último rei persa da dinastia aquemênida. Perdeu para Alexandre Magno em Isso (333 a.C.) e em Gaugamela (331 a.C.). Foi morto em 330 a.C. por conspiradores do próprio lado.","s":"Darius III (Wikipedia)","u":"https://en.wikipedia.org/wiki/Darius_III"},{"t":"Alexandre Magno morreu em 10 de junho de 323 a.C. Seus generais, os Diádocos, brigaram pelo império por cerca de 50 anos. Surgiram os reinos dos Ptolomeus, dos Selêucidas e dos Antigônidas.","s":"Wars of the Diadochi (Wikipedia)","u":"https://en.wikipedia.org/wiki/Wars_of_the_Diadochi"}],"6":[{"t":"Florença fez guerra a Pisa a partir de 1497, sem sucesso. Maquiavel, como responsável pela guerra da República, ajudou a retomar Pisa em 1509.","s":"Republic of Florence (Wikipedia)","u":"https://en.wikipedia.org/wiki/Republic_of_Florence"}],"7":[{"t":"Ciro, o Grande, fundou o Império Persa aquemênida. Derrubou os medos, conquistou a Lídia e, em 539 a.C., a Babilônia. Morreu em 530 a.C.","s":"Cyrus the Great (Wikipedia)","u":"https://en.wikipedia.org/wiki/Cyrus_the_Great"},{"t":"Frei Girolamo Savonarola pregava em Florença contra a corrupção. Depois da expulsão dos Médici, em 1494, teve grande influência na cidade. Foi excomungado em 1497 e enforcado e queimado em 23 de maio de 1498.","s":"Girolamo Savonarola (Wikipedia)","u":"https://en.wikipedia.org/wiki/Girolamo_Savonarola"}],"8":[{"t":"César Bórgia era filho do papa Alexandre VI. Com apoio do pai e de tropas francesas, tomou cidades da Romanha, como Ímola, Forlì, Rimini e Faenza. Maquiavel o observou de perto como diplomata, de outubro de 1502 a janeiro de 1503.","s":"Cesare Borgia (Wikipedia)","u":"https://en.wikipedia.org/wiki/Cesare_Borgia"},{"t":"Rodrigo Bórgia foi o papa Alexandre VI de 1492 até morrer, em 18 de agosto de 1503. Quando ele morreu, César, o filho, também estava doente e perdeu seu principal apoio.","s":"Pope Alexander VI (Wikipedia)","u":"https://en.wikipedia.org/wiki/Pope_Alexander_VI"}],"9":[{"t":"Agátocles, tirano de Siracusa, tomou o poder em 317 a.C., quando seus soldados mataram milhares de ricos. Atacou Cartago na África em 310 a.C., tornou-se rei em 304 a.C. e morreu em 289 a.C.","s":"Agathocles of Syracuse (Wikipedia)","u":"https://en.wikipedia.org/wiki/Agathocles_of_Syracuse"},{"t":"Oliverotto Euffreducci tomou o poder em Fermo convidando o tio e cidadãos importantes para um banquete, onde soldados os mataram. Em 31 de dezembro de 1502, César Bórgia o mandou estrangular em Senigallia.","s":"Oliverotto Euffreducci (Wikipedia)","u":"https://en.wikipedia.org/wiki/Oliverotto_Euffreducci"}],"10":[{"t":"Nábis foi o último rei independente de Esparta (cerca de 207 a 192 a.C.). Foi derrotado por Filopêmen, general da Liga Aqueia, e assassinado pelos etólios em 192 a.C.","s":"Nabis of Sparta (Wikipedia)","u":"https://en.wikipedia.org/wiki/Nabis_of_Sparta"}],"12":[{"t":"Júlio II foi papa de 1503 a 1513 e ficou conhecido como o «papa guerreiro»: liderou tropas pessoalmente. Em 1506 tomou Bolonha e Perúgia. Em 1508 encomendou a Michelangelo o teto da Capela Sistina.","s":"Pope Julius II (Wikipedia)","u":"https://en.wikipedia.org/wiki/Pope_Julius_II"},{"t":"Giovanni de Médici, filho de Lorenzo, o Magnífico, foi o papa Leão X de 1513 a 1521. Foi feito cardeal aos 13 anos. Protegeu artistas como Rafael.","s":"Pope Leo X (Wikipedia)","u":"https://en.wikipedia.org/wiki/Pope_Leo_X"}],"13":[{"t":"«Condottiero» vem de «condotta», o contrato de um capitão mercenário. Cidades ricas como Veneza e Florença, com exércitos pequenos, contratavam esses capitães. Alguns acabaram fundando seus próprios Estados.","s":"Condottieri (Wikipedia)","u":"https://en.wikipedia.org/wiki/Condottieri"},{"t":"Em 14 de maio de 1509, em Agnadello, os franceses de Luís XII derrotaram os venezianos, que perderam mais de 4 mil homens. Maquiavel escreveu que Veneza perdeu num dia o que levou séculos para conquistar.","s":"Battle of Agnadello (Wikipedia)","u":"https://en.wikipedia.org/wiki/Battle_of_Agnadello"}],"14":[{"t":"Hierão II governou Siracusa de 275 a 215 a.C. Foi general de Pirro e se aliou a Roma em 263 a.C., permanecendo leal durante a Primeira Guerra Púnica.","s":"Hiero II of Syracuse (Wikipedia)","u":"https://en.wikipedia.org/wiki/Hiero_II_of_Syracuse"}],"15":[{"t":"Filopêmen (253-183 a.C.) foi oito vezes general da Liga Aqueia, na Grécia. Reformou o exército, a partir de 209 a.C., e venceu Nábis, de Esparta, em Tégea.","s":"Philopoemen (Wikipedia)","u":"https://en.wikipedia.org/wiki/Philopoemen"}],"18":[{"t":"Aníbal, general de Cartago, atravessou os Alpes em 218 a.C. e venceu os romanos em Canas (216 a.C.). Seu exército misturava cartagineses, ibéricos, gauleses, númidas e líbios.","s":"Hannibal (Wikipedia)","u":"https://en.wikipedia.org/wiki/Hannibal"},{"t":"Cipião Africano assumiu o comando romano na Hispânia em 210 a.C. Em 202 a.C. venceu Aníbal em Zama, o que encerrou a Segunda Guerra Púnica.","s":"Scipio Africanus (Wikipedia)","u":"https://en.wikipedia.org/wiki/Scipio_Africanus"}],"20":[{"t":"Sétimo Severo foi imperador romano de 193 a 211. Nasceu em Leptis Magna, na atual Líbia. As legiões do Danúbio o apoiaram, e ele dissolveu a Guarda Pretoriana. Morreu em York, em 211.","s":"Septimius Severus (Wikipedia)","u":"https://en.wikipedia.org/wiki/Septimius_Severus"},{"t":"Giovanni II Bentivoglio governou Bolonha de fato de 1463 a 1506. O papa Júlio II o depôs em outubro de 1506, com ajuda de tropas francesas. Ele morreu preso em Milão, em 1508.","s":"Giovanni II Bentivoglio (Wikipedia)","u":"https://en.wikipedia.org/wiki/Giovanni_II_Bentivoglio"}],"21":[{"t":"Caterina Sforza governou Forlì e Ímola. Depois do assassinato do marido, em 1488, resistiu na fortaleza de Ravaldino. Em janeiro de 1500, as tropas de César Bórgia tomaram essa fortaleza e a prenderam.","s":"Caterina Sforza (Wikipedia)","u":"https://en.wikipedia.org/wiki/Caterina_Sforza"}],"22":[{"t":"Fernando II reinou em Aragão de 1479 a 1516. Casado com Isabel de Castela, completou em 1492 a conquista de Granada. Depois de lutar contra a França, ficou com o reino de Nápoles.","s":"Ferdinand II of Aragon (Wikipedia)","u":"https://en.wikipedia.org/wiki/Ferdinand_II_of_Aragon"}],"23":[{"t":"Pandolfo Petrucci (1452-1512) foi senhor de Siena. Em 1502, evitou o encontro de Senigallia, onde César Bórgia matou seus capitães. Fugiu de Siena em janeiro de 1503.","s":"Pandolfo Petrucci (Wikipedia)","u":"https://en.wikipedia.org/wiki/Pandolfo_Petrucci"}],"24":[{"t":"Maximiliano I foi imperador do Sacro Império de 1508 a 1519. Era chamado de «Massimiliano di pochi denari» (Maximiliano sem dinheiro) porque suas campanhas na Itália correram mal.","s":"Maximilian I, Holy Roman Emperor (Wikipedia)","u":"https://en.wikipedia.org/wiki/Maximilian_I,_Holy_Roman_Emperor"}],"25":[{"t":"As Guerras da Itália terminaram com o Tratado de Cateau-Cambrésis, em 3 de abril de 1559. A França deixou a Itália, e a Espanha ficou com Nápoles, a Sicília e o ducado de Milão.","s":"Italian Wars (Wikipedia)","u":"https://en.wikipedia.org/wiki/Italian_Wars"}],"26":[{"t":"Em 1506, o papa Júlio II comandou pessoalmente a campanha que expulsou Giovanni Bentivoglio de Bolonha e Gian Paolo Baglioni de Perúgia.","s":"Pope Julius II (Wikipedia)","u":"https://en.wikipedia.org/wiki/Pope_Julius_II"}],"27":[{"t":"Em setembro de 1512, o cardeal Giovanni de Médici tomou Florença com tropas papais e a família Médici voltou ao poder, depois de 18 anos de exílio.","s":"Republic of Florence (Wikipedia)","u":"https://en.wikipedia.org/wiki/Republic_of_Florence"}]}},"racconti":{"intro":[{"t":"Carlo Collodi é o nome de escritor de Carlo Lorenzini, nascido em Florença em 1826. Ele tirou o nome de Collodi, a cidade de sua mãe. Foi voluntário nas guerras de independência italianas em 1848 e 1860.","s":"Wikipedia: Carlo Collodi","u":"https://en.wikipedia.org/wiki/Carlo_Collodi"},{"t":"Em 1861 foi proclamado o Reino da Itália. Florença foi sede do governo de 1865 a 1871, quando Roma virou capital. Collodi publicou este livro em 1876, nessa Itália recém-unida.","s":"Wikipedia: Unification of Italy","u":"https://en.wikipedia.org/wiki/Unification_of_Italy"},{"t":"O editor Felice Paggi encomendou a tradução em 1875, e o livro saiu em Florença em 1876. Pinocchio só veio depois: a primeira parte saiu em 7 de julho de 1881, em revista.","s":"Wikipedia: Carlo Collodi (it)","u":"https://it.wikipedia.org/wiki/Carlo_Collodi"},{"t":"O livro traduz uma antologia francesa da editora Hachette, com contos de Perrault, de Madame d'Aulnoy e de Madame Leprince de Beaumont. Na folha de rosto aparece só o nome de Collodi; as autoras e o autor ficam no índice, no fim.","s":"Bouchard, «Carlo Collodi, traducteur des contes de fées» (Convergences francophones, 2015)","u":"https://mrujs.mtroyal.ca/index.php/cf/article/download/257/BOUCHARD-ART/647"},{"t":"Collodi não traduziu palavra por palavra. Ele trocou o estilo de corte por um tom de conversa, de sabor toscano, e suavizou algumas moralidades. Por isso o texto soa como um narrador falando com você.","s":"Giulia Donato, «Collodi scrittore di fiabe» (Università degli Studi di Milano)","u":"https://www.fondazionemondadori.it/wp-content/uploads/2018/12/Donato-Giulia.pdf"},{"t":"O nome «conte de fées» (conto de fadas) vem da França do fim do século XVII. Madame d'Aulnoy publicou em 1697 a coletânea «Les Contes des Fées» e recebia convidados em seu salão em Paris.","s":"Wikipedia: Madame d'Aulnoy","u":"https://en.wikipedia.org/wiki/Madame_d%27Aulnoy"}],"ch":{"1":[{"t":"A versão de Perrault de Barba Azul foi publicada em Paris em 1697, no livro «Histoires ou contes du temps passé».","s":"Wikipedia: Bluebeard","u":"https://en.wikipedia.org/wiki/Bluebeard"},{"t":"Esse livro de 1697 foi publicado com o nome do filho mais novo de Perrault, Pierre Perrault Darmancourt. Provavelmente foi para evitar críticas dos «Antigos».","s":"Wikipedia: Charles Perrault","u":"https://en.wikipedia.org/wiki/Charles_Perrault"}],"2":[{"t":"Antes de Perrault (1697), o italiano Basile contou uma versão em «Sol, Lua e Talia» (1634-1636). Na versão francesa de Perrault não há beijo, e os filhos da princesa se chamam Aurora e Dia.","s":"Wikipedia: Sleeping Beauty","u":"https://en.wikipedia.org/wiki/Sleeping_Beauty"}],"3":[{"t":"Perrault publicou «Cendrillon» em 1697 e acrescentou a abóbora, a fada madrinha e o sapatinho de vidro. Antes dele, Basile já tinha uma Cenerentola italiana, de 1634.","s":"Wikipedia: Cinderella","u":"https://en.wikipedia.org/wiki/Cinderella"},{"t":"Em 11 de outubro de 1875, o jornal Fanfulla publicou a tradução de «Cenerentola» feita por Collodi, para anunciar a coletânea que vinha por aí.","s":"Giulia Donato, «Collodi scrittore di fiabe» (Università degli Studi di Milano)","u":"https://www.fondazionemondadori.it/wp-content/uploads/2018/12/Donato-Giulia.pdf"}],"4":[{"t":"Perrault publicou «Le Petit Poucet» em 1697. A primeira metade lembra João e Maria: o menino marca o caminho primeiro com pedrinhas brancas e depois com migalhas, que os pássaros comem.","s":"Wikipedia: Hop-o'-My-Thumb","u":"https://en.wikipedia.org/wiki/Hop-o%27-My-Thumb"}],"5":[{"t":"A versão em prosa de «Pele de Burro» presente na antologia francesa foi publicada em 1781 por um editor chamado Lamy. O original de Perrault era em versos, de 1694.","s":"Bouchard, «Carlo Collodi, traducteur des contes de fées» (Convergences francophones, 2015)","u":"https://mrujs.mtroyal.ca/index.php/cf/article/download/257/BOUCHARD-ART/647"}],"6":[{"t":"Perrault chamou o conto de «Les Fées». A moça gentil com uma velha junto ao poço solta joias ou flores ao falar. A irmã grosseira solta sapos ou cobras.","s":"Wikipedia: Diamonds and Toads","u":"https://en.wikipedia.org/wiki/Diamonds_and_Toads"}],"7":[{"t":"Em Perrault (1697), o lobo come a menina e não há caçador para salvá-la. Perrault é quem dá a ela o capuz vermelho. O caçador só aparece na versão dos Grimm, de 1812.","s":"Wikipedia: Little Red Riding Hood","u":"https://en.wikipedia.org/wiki/Little_Red_Riding_Hood"}],"8":[{"t":"A versão escrita mais antiga é de Straparola (por volta de 1550-1553). Basile contou outra em 1634 («Cagliuso»). A de Perrault saiu em 1697 e é a mais famosa.","s":"Wikipedia: Puss in Boots","u":"https://en.wikipedia.org/wiki/Puss_in_Boots"}],"9":[{"t":"Perrault publicou «Riquet à la houppe» em 1697. Ele foi influenciado por uma versão anterior, de 1696, escrita por Catherine Bernard no romance «Inès de Cordoue».","s":"Wikipedia: Ricky of the Tuft","u":"https://en.wikipedia.org/wiki/Ricky_of_the_Tuft"}],"10":[{"t":"A partir deste conto, as histórias não são de Perrault. «La Belle aux cheveux d'or» é de Madame d'Aulnoy e vem da coletânea de 1697, segundo o estudo de Bouchard.","s":"Bouchard, «Carlo Collodi, traducteur des contes de fées» (Convergences francophones, 2015)","u":"https://mrujs.mtroyal.ca/index.php/cf/article/download/257/BOUCHARD-ART/647"}],"11":[{"t":"«L'Oiseau bleu», de Madame d'Aulnoy, saiu em 1697 em «Les Contes des Fées». Um príncipe vira pássaro azul e visita a princesa Florine na torre.","s":"Wikipedia: The Blue Bird (fairy tale)","u":"https://en.wikipedia.org/wiki/The_Blue_Bird_(fairy_tale)"},{"t":"Um trecho desse conto virou número de dança no 3º ato do balé «A Bela Adormecida». Jean-Paul Sartre citou o conto entre os primeiros livros de que gostou na infância.","s":"Wikipedia: The Blue Bird (fairy tale)","u":"https://en.wikipedia.org/wiki/The_Blue_Bird_(fairy_tale)"}],"12":[{"t":"«La Chatte blanche», de Madame d'Aulnoy, saiu em 1698 em «Contes nouveaux ou Les Fées à la mode». O filho caçula do rei recebe do gato branco ajuda para cumprir três tarefas.","s":"Wikipedia: The White Cat (fairy tale)","u":"https://en.wikipedia.org/wiki/The_White_Cat_(fairy_tale)"}],"13":[{"t":"«La Biche au bois» (a corça na floresta) é de Madame d'Aulnoy e saiu em 1698, na coletânea «Contes nouveaux ou Les Fées à la mode».","s":"Wikipedia: Madame d'Aulnoy","u":"https://en.wikipedia.org/wiki/Madame_d%27Aulnoy"},{"t":"A princesa Desirée é criada longe do sol, por causa de uma maldição. Quando a luz do sol a toca, ela vira uma corça branca. À noite, o príncipe a encontra em forma humana.","s":"Wikipedia: The Hind in the Wood","u":"https://en.wikipedia.org/wiki/The_Hind_in_the_Wood"}],"14":[{"t":"«Le Prince Chéri» é de Madame Leprince de Beaumont e vem do livro educativo «Le Magasin des enfants» (Londres, 1757), feito para ensinar crianças, como indica o estudo.","s":"Bouchard, «Carlo Collodi, traducteur des contes de fées» (Convergences francophones, 2015)","u":"https://mrujs.mtroyal.ca/index.php/cf/article/download/257/BOUCHARD-ART/647"},{"t":"Madame Leprince de Beaumont nasceu em Rouen em 1711. Saiu da França para trabalhar como governanta em Londres e voltou em 1763.","s":"Wikipedia: Jeanne-Marie Leprince de Beaumont","u":"https://en.wikipedia.org/wiki/Jeanne-Marie_Leprince_de_Beaumont"}],"15":[{"t":"A história original é de Gabrielle-Suzanne de Villeneuve, de 1740. Madame Leprince de Beaumont a resumiu e reescreveu em «Magasin des enfants». A versão curta é a mais conhecida.","s":"Wikipedia: Beauty and the Beast","u":"https://en.wikipedia.org/wiki/Beauty_and_the_Beast"}]}}};
